                <FormField key={f.name} field={f} value={values[f.name]} onChange={setValue} />
              ))}
          </>
        )}

        {create.phase === 'error' && create.status === 409 && (
          <label className="force-row">
            <input type="checkbox" checked={force} onChange={(e) => setForce(e.target.checked)} />
            render into the non-empty directory anyway
          </label>
        )}

        <div className="form-actions">
          <button type="submit" className="run-btn" disabled={!canRun}>
            {create.phase === 'running' ? 'creating…' : 'int create'}
          </button>
        </div>
      </form>

      {create.phase === 'error' && (
        <div className="banner error">{create.message}</div>
      )}
      {create.phase === 'done' && (
        <div className="create-result">
          <div className="create-result-head">
            created <code>{create.result.outputDir}</code> from {create.result.owner}/
            {create.result.repo}@{create.result.version}
          </div>
          {create.result.dependencies && create.result.dependencies.length > 0 && (
            <ul className="create-deps">
              {create.result.dependencies.map((d) => (
                <li key={d.outputDir}>
                  {d.template} → {d.outputDir} <em>({d.action})</em>
                </li>
              ))}
            </ul>
          )}
          <button className="flow-refresh" onClick={() => onCreated(create.result.outputDir)}>
            view in catalog
          </button>
        </div>
      )}
    </div>
  )
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}

import { useCallback, useEffect, useState } from 'react'
import {
  api,
  type CreateResponse,
  type TemplateDetail,
  type TemplateList,
} from '../api'
import { Field, FormField } from './form'
import { useTemplateFields } from './useTemplateFields'

interface Props {
  /** Switch to the catalog with the newly created integration selected. */
  onCreated: (path: string) => void
}

type CreateState =
  | { phase: 'idle' }
  | { phase: 'running' }
  | { phase: 'done'; result: CreateResponse }
  | { phase: 'error'; message: string; status: number }

// TemplatesView is the `template` + `int create` surface: a list of the
// library's templates on the left, the selected one's manifest rendered as a
// form on the right, and a Run button that renders it into the workspace.
export function TemplatesView({ onCreated }: Props) {
  const [list, setList] = useState<TemplateList | null>(null)
  const [listError, setListError] = useState<string | null>(null)
  const [selected, setSelected] = useState<string | null>(null)

  useEffect(() => {
    api
      .listTemplates()
      .then(setList)
      .catch((e: unknown) => setListError(errText(e)))
  }, [])

  // Auto-select the first template once the list loads.
  useEffect(() => {
    if (list && list.templates.length > 0 && !selected) {
      setSelected(list.templates[0])
    }
  }, [list, selected])

  if (listError) {
    return <div className="banner error">{listError}</div>
  }
  if (!list) {
    return <div className="empty">loading templates…</div>
  }
  if (list.templates.length === 0) {
    return (
      <div className="empty">
        no templates in {list.owner}/{list.repo}@{list.version}
      </div>
    )
  }

  return (
    <div className="templates-view">
      <aside className="templates-list">
        <div className="templates-list-head">
          <span className="sidebar-title">Templates</span>
          <span className="count">{list.templates.length}</span>
        </div>
        <div className="templates-lib">
          {list.owner}/{list.repo}@{list.version}
        </div>
        <ul>
          {list.templates.map((name) => (
            <li key={name}>
              <button
                className={`template-item${selected === name ? ' active' : ''}`}
                onClick={() => setSelected(name)}
                aria-current={selected === name ? 'page' : undefined}
              >
                {name}
              </button>
            </li>
          ))}
        </ul>
      </aside>
      <section className="templates-detail">
        {selected ? (
          <TemplatePanel key={selected} name={selected} onCreated={onCreated} />
        ) : (
          <div className="empty">select a template</div>
        )}
      </section>
    </div>
  )
}

// TemplatePanel renders one template's manifest as the create form. It is
// keyed by template name, so switching templates resets all form state.
function TemplatePanel({ name, onCreated }: { name: string; onCreated: Props['onCreated'] }) {
  const [detail, setDetail] = useState<TemplateDetail | null>(null)
  const [error, setError] = useState<string | null>(null)
  // The templates view scaffolds into the workspace root, so it derives
  // from the whole workspace — the same context `int create` run there
  // prompts with.
====
	owner         string
	repo          string
	githubBaseURL string
}

// fetchLibrary resolves and downloads the provider's library release. The
// caller owns the returned Library and must Close it.
func (p templatesProvider) fetchLibrary(ctx context.Context) (*template.Library, error) {
	return template.FetchLibrary(ctx, template.LibraryOptions{
		Version:       p.version,
		UserAgent:     p.userAgent,
		Owner:         p.owner,
		Repo:          p.repo,
		GitHubBaseURL: p.githubBaseURL,
	})
}

// createRequest is the POST /api/templates/{name}/create body.
type createRequest struct {
	// Name picks the output directory under the workspace root — the CLI's
	// --out-dir. It is deliberately decoupled from values.name, the schema
	// parameter: a template can want a PascalCase project name next to a
	// kebab-case directory, and the CLI separates the two the same way
	// (--set name=X --out-dir y). Required.
	Name string `json:"name"`

	// Dir is the root-relative, slash-separated directory the output renders
	// under; "" or "." is the workspace root — the pre-Dir behavior. It must
	// already exist: the endpoint scaffolds into systems, it does not invent
	// directory trees.
	Dir string `json:"dir,omitempty"`

	// Values are the template parameters, as --set would supply them.
	Values map[string]any `json:"values"`

	// Force allows rendering into a non-empty output directory.
	Force bool `json:"force,omitempty"`
}

// createResponse is the 201 payload: CreateResult with the output directory
// made root-relative, matching the identifier space /api/integrations uses.
type createResponse struct {
	*template.CreateResult
	// Diagnostics is what the render wrote to stderr, one entry per line —
	// the fetch notice and each dependency render. Provenance, not failure.
	Diagnostics []string `json:"diagnostics,omitempty"`
}

// maxCreateBodyBytes caps a create request body. Parameter values are short
// scalars; a megabyte is already generous and keeps a malformed client from
// streaming unbounded input into memory.
const maxCreateBodyBytes = 1 << 20

// templateSummary is one list entry with the manifest metadata the create
// surfaces filter on — notably the intropy.dev/* labels a flow-view slot
// selects templates by. Additive beside the bare names `templates` keeps.
type templateSummary struct {
	Name        string            `json:"name"`
	Title       string            `json:"title,omitempty"`
	Description string            `json:"description,omitempty"`
	Labels      map[string]string `json:"labels,omitempty"`
}

// listTemplates mirrors `template list -o json` against the server's library
// release, adding per-template metadata (`entries`) on top of the names. The
// describes are local reads on the already-extracted tarball; one malformed
// manifest drops that entry rather than hiding the rest of the library.
func (s *apiServer) listTemplates(w http.ResponseWriter, r *http.Request) {
	lib, err := s.templates.fetchLibrary(r.Context())
	if err != nil {
		writeError(w, http.StatusBadGateway, err.Error())
		return
	}
	defer lib.Close()

