func workspaceRootOf(outputDir string) string {
	if outputDir == "" {
		return "."
	}
	return filepath.Dir(outputDir)
}

// printWarning reports a workspace-scan issue without failing the create —
// a malformed sibling record must not block scaffolding a new component.
func printWarning(stderr io.Writer, w error) {
	fmt.Fprintf(stderr, "warning: %v\n", w)
}

// resolveCreateName folds the -n shorthand into the set map and derives the
// output dir. -n is sugar for --set name=<v>; it also defaults the output
// dir to the kebab-cased name when -o is absent — the same normalization
// sys create applies, so a name and its kebab form are one component.
func resolveCreateName(name, output string, sets map[string]any) (string, error) {
	if name == "" {
		return output, nil
	}
	if _, ok := sets["name"]; ok {
		return "", newUsageErrorf("cannot combine --name with --set name= (they conflict)")
	}
	sets["name"] = name
	if output == "" {
		output = xstrings.ToKebabCase(name)
	}
	return output, nil
}

// deriveOutDir runs the create far enough to resolve values and returns the
// manifest's spec.values.outDir rendering — the template-declared directory
// for runs that name neither --name nor --out-dir. A manifest without the
// entry is the usage error --out-dir would have spared.
func deriveOutDir(opts template.CreateOptions) (string, error) {
	prep, err := template.PrepareCreate(cmdContext(opts), opts)
	if err != nil {
		return "", err
	}
	defer prep.Cleanup()
	if prep.Manifest.Spec.Values["outDir"] == "" {
		return "", newUsageErrorf("--out-dir is required (template %q declares no spec.values.outDir default)", opts.Template)
	}
	dir, ok := prep.Values["outDir"].(string)
	if !ok || dir == "" {
		return "", fmt.Errorf("template %q spec.values.outDir rendered empty", opts.Template)
	}
	if filepath.Base(dir) != dir {
		return "", fmt.Errorf("template %q spec.values.outDir rendered %q (must be a single path segment)", opts.Template, dir)
	}
	return dir, nil
}

