// outDirLibraryServer fakes the GitHub endpoints deriveOutDir's fetch
// calls: the release lookup and a tarball holding one template whose
// manifest carries the given spec.values.
func outDirLibraryServer(t *testing.T, values string) *httptest.Server {
	t.Helper()
	manifest := `apiVersion: intropy.dev/v1
kind: Template
metadata:
  name: hello-world
spec:
  parameters:
    type: object
    required: [integrationName]
    properties:
      integrationName:
        type: string
`
	if values != "" {
		manifest += "  values:\n" + values
	}
	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	tw := tar.NewWriter(gz)
	for name, body := range map[string]string{
		"o-r-abc/hello-world/template.yaml":           manifest,
		"o-r-abc/hello-world/skeleton/README.md.tmpl": "{{ .integrationName }}\n",
	} {
		if err := tw.WriteHeader(&tar.Header{Name: name, Mode: 0o644, Size: int64(len(body))}); err != nil {
			t.Fatal(err)
		}
		if _, err := tw.Write([]byte(body)); err != nil {
			t.Fatal(err)
		}
	}
	if err := tw.Close(); err != nil {
		t.Fatal(err)
	}
	if err := gz.Close(); err != nil {
		t.Fatal(err)
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/repos/o/r/releases/latest", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"tag_name":"v1"}`))
	})
	mux.HandleFunc("/repos/o/r/tarball/v1", func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write(buf.Bytes())
	})
	srv := httptest.NewServer(mux)
	t.Cleanup(srv.Close)
	return srv
}

func deriveOutDirOpts(srv *httptest.Server, sets map[string]any) template.CreateOptions {
	var stderr bytes.Buffer
	return template.CreateOptions{
		Template:      "hello-world",
		SetValues:     sets,
		NoInput:       true,
		Stderr:        &stderr,
		HTTP:          srv.Client(),
		Owner:         "o",
		Repo:          "r",
		GitHubBaseURL: srv.URL,
	}
}

func TestDeriveOutDir(t *testing.T) {
	t.Run("manifest derivation names the directory", func(t *testing.T) {
		srv := outDirLibraryServer(t, "    outDir: '{{ .integrationName | kebabcase }}'\n")
		out, err := deriveOutDir(context.Background(), deriveOutDirOpts(srv, map[string]any{"integrationName": "OrderSync"}))
		if err != nil {
			t.Fatalf("deriveOutDir: %v", err)
		}
		if out != "order-sync" {
			t.Errorf("out = %q, want order-sync", out)
		}
	})

	t.Run("no manifest default is a usage error", func(t *testing.T) {
		srv := outDirLibraryServer(t, "")
		_, err := deriveOutDir(context.Background(), deriveOutDirOpts(srv, map[string]any{"integrationName": "x"}))
		if err == nil {
			t.Fatal("expected error, got nil")
		}
		var ue *usageError
		if !errors.As(err, &ue) {
			t.Errorf("error %v is not a usageError", err)
		}
	})

	t.Run("nested derivation is refused", func(t *testing.T) {
		srv := outDirLibraryServer(t, "    outDir: 'nested/{{ .integrationName | kebabcase }}'\n")
		_, err := deriveOutDir(context.Background(), deriveOutDirOpts(srv, map[string]any{"integrationName": "x"}))
		if err == nil || !strings.Contains(err.Error(), "single path segment") {
			t.Errorf("expected single-segment refusal, got %v", err)
		}
	})
}

