func TestDeriveOutDir(t *testing.T) {
	t.Run("manifest derivation names the directory", func(t *testing.T) {
		srv := outDirLibraryServer(t, "    outDir: '{{ .integrationName | kebabcase }}'\n")
		out, err := deriveOutDir(context.Background(), deriveOutDirOpts(srv, map[string]any{"integrationName": "OrderSync"}))
		if err != nil {
			t.Fatalf("deriveOutDir: %v", err)
		}
		if out != "order-sync" {
			t.Errorf("out = %q, want order-sync", out)
		}
	})

	t.Run("no manifest default is a usage error", func(t *testing.T) {
		srv := outDirLibraryServer(t, "")
		_, err := deriveOutDir(context.Background(), deriveOutDirOpts(srv, map[string]any{"integrationName": "x"}))
		if err == nil {
			t.Fatal("expected error, got nil")
		}
		var ue *usageError
		if !errors.As(err, &ue) {
			t.Errorf("error %v is not a usageError", err)
		}
	})

	t.Run("nested derivation is refused", func(t *testing.T) {
		srv := outDirLibraryServer(t, "    outDir: 'nested/{{ .integrationName | kebabcase }}'\n")
		_, err := deriveOutDir(context.Background(), deriveOutDirOpts(srv, map[string]any{"integrationName": "x"}))
		if err == nil || !strings.Contains(err.Error(), "single path segment") {
			t.Errorf("expected single-segment refusal, got %v", err)
		}
	})
}
